    }

    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 32px;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top left, #dce7ff 0, transparent 28%),
        radial-gradient(circle at bottom right, #fbe7ef 0, transparent 24%),
        var(--bg);
    }

    .page {
      width: min(920px, 100%);
      display: grid;
      gap: 24px;
      grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
      align-items: center;
    }

    .hero {
      padding: 20px 8px;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      margin: 0 0 12px;
      padding: 8px 12px;
      border: 1px solid var(--line);
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.65);
      color: var(--muted);
      font-size: 0.9rem;
      font-weight: 600;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 4vw, 3.6rem);
      line-height: 1.05;
      letter-spacing: -0.04em;
    }

    .hero p {
      margin: 16px 0 0;
      max-width: 38ch;
      font-size: 1.05rem;
      line-height: 1.6;
      color: var(--muted);
    }

    .preview-card {
      padding: 18px;
      border: 1px solid rgba(255, 255, 255, 0.7);
      border-radius: calc(var(--radius) + 6px);
      background: var(--surface);
      box-shadow: var(--shadow);
      backdrop-filter: blur(18px);
    }

    .preview-image {
      display: block;
      width: 100%;
      aspect-ratio: 4 / 3;
      object-fit: cover;
      border-radius: calc(var(--radius) - 6px);
      border: 1px solid rgba(19, 34, 56, 0.08);
      background: #e8eefc;
    }

    .meta {
      display: flex;
      justify-content: space-between;
      gap: 12px;
      align-items: center;
      padding-top: 16px;
    }

    .meta h2 {
      margin: 0 0 4px;
      font-size: 1.05rem;
    }

    .meta p {
      margin: 0;
      color: var(--muted);
      font-size: 0.95rem;
    }

    button {
      font: inherit;
      border: 0;
      cursor: pointer;
      transition: transform 0.15s ease, background-color 0.15s ease, opacity 0.15s ease;
    }

    button:focus-visible {
      outline: 3px solid rgba(36, 87, 255, 0.32);
      outline-offset: 3px;
    }

    .trigger,
    .secondary,
    .danger {
      padding: 12px 18px;
      border-radius: 999px;
      font-weight: 700;
    }

    .trigger {
      color: #fff;
      background: var(--danger);
      box-shadow: 0 12px 24px rgba(214, 69, 69, 0.26);
    }

    .trigger:hover {
      background: var(--danger-hover);
    }

    .trigger:active,
    .secondary:active,
    .danger:active {
      transform: translateY(1px);
    }

    dialog {
      width: min(92vw, 480px);
      padding: 0;
      border: 1px solid rgba(19, 34, 56, 0.12);
      border-radius: 28px;
      background: var(--surface-strong);
      box-shadow: var(--shadow);
      color: var(--text);
    }

    dialog::backdrop {
      background: rgba(11, 18, 32, 0.5);
      backdrop-filter: blur(8px);
    }

    .modal {
      padding: 24px;
    }

    .modal-header {
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      gap: 16px;
      margin-bottom: 12px;
    }

    .modal h2 {
      margin: 0;
      font-size: 1.5rem;
      letter-spacing: -0.02em;
    }

    .close {
      width: 40px;
      height: 40px;
      border-radius: 50%;
      background: #eef2ff;
      color: #33415c;
      font-size: 1.25rem;
      line-height: 1;
    }

    .modal p {
      margin: 0;
      color: var(--muted);
      line-height: 1.6;
    }

    .actions {
      display: flex;
      gap: 12px;
      justify-content: flex-end;
      margin-top: 24px;
      flex-wrap: wrap;
    }

    .secondary {
      background: #edf2fb;
      color: var(--text);
    }

    .danger {
      background: var(--danger);
      color: #fff;
    }

    .secondary:hover {
      background: #e3eaf7;
    }

    .danger:hover {
      background: var(--danger-hover);
    }

    .status {
      min-height: 1.25rem;
      margin-top: 12px;
      color: #25643d;
      font-weight: 600;
    }

    @media (max-width: 640px) {
      body {
        padding: 20px;
      }

      .meta {
        flex-direction: column;
        align-items: stretch;
      }

      .trigger {
        width: 100%;
      }

      .actions {
        flex-direction: column-reverse;
      }

      .actions button {
        width: 100%;
      }
    }
  </style>
</head>
