      <div class="actions">
        <button class="secondary" type="button">Cancel</button>
        <button class="danger" type="button">Delete</button>
      </div>
    </div>
  </dialog>

  <script>
    const dialog = document.getElementById('delete-dialog');
    const trigger = document.querySelector('.trigger');
    const closeButtons = dialog.querySelectorAll('.close, .secondary');
    const deleteButton = dialog.querySelector('.danger');
    const status = document.getElementById('status');
    const previewCard = document.querySelector('.preview-card');

    function openDialog() {
      dialog.showModal();
    }

    function closeDialog() {
      dialog.close();
      trigger.focus();
    }

    trigger.addEventListener('click', openDialog);
    closeButtons.forEach((button) => button.addEventListener('click', closeDialog));

    deleteButton.addEventListener('click', () => {
      dialog.close();
      previewCard.style.opacity = '0.5';
      previewCard.style.pointerEvents = 'none';
      status.textContent = 'Image deleted from your library.';
      trigger.disabled = true;
      trigger.textContent = 'Deleted';
    });

    dialog.addEventListener('click', (event) => {
      const rect = dialog.getBoundingClientRect();
      const inDialog =
        event.clientX >= rect.left &&
        event.clientX <= rect.right &&
        event.clientY >= rect.top &&
        event.clientY <= rect.bottom;

      if (!inDialog) {
        closeDialog();
      }
    });

    dialog.addEventListener('cancel', () => {
      closeDialog();
    });
  </script>
